'}, {'type': 'input_text', 'text': 'function [obj,params] = loadSessionData(meta,params, varargin)

% varargin only accepts one input right now -> params.behav_only. If 1,
% don't process clusters
if nargin > 2
    behav_only = varargin{1};
else
    behav_only = 0;
end

disp("LOADING ALL DATA OBJECTS")
obj = loadObjs(meta);


for sessix = 1:numel(meta)
    for prbix = 1:numel(params.probe{sessix})
        disp('______________________________________________________')
        disp(['Processing data for session ' [meta(sessix).anm '_' meta(sessix).date ' | Probe' num2str(params.probe{sessix}(prbix))   ]])
        disp(' ')

        prbnum = params.probe{sessix}(prbix);

        [sessparams{sessix,prbix},sessobj{sessix,prbix}] = processData(obj(sessix),params,prbnum, behav_only);
    end
end

% clean up sessparams and sessobj
for sessix = 1:numel(meta)
    params.trialid{sessix} = sessparams{sessix}.trialid;

    if numel(params.probe{sessix}) == 1
        params.cluid{sessix} = sessparams{sessix,1}.cluid{params.probe{sessix}};
        params.cluid_all{sessix} = params.cluid{sessix};
        params.probeid{sessix} = sessparams{sessix,1}.probeid{params.probe{sessix}};
        params.probeid_all{sessix} = params.probeid{sessix};

        objs(sessix) = sessobj{sessix,1};

        if behav_only
            continue;
        end

        objs(sessix).psth = objs(sessix).psth{params.probe{sessix}};
        objs(sessix).trialdat = objs(sessix).trialdat{params.probe{sessix}};
        objs(sessix).presampleFR = objs(sessix).presampleFR{params.probe{sessix}};
        objs(sessix).presampleSigma = objs(sessix).presampleSigma{params.probe{sessix}};
    elseif numel(params.probe{sessix}) == 2 % concatenate both probes worth of data

        params.cluid{sessix} = {sessparams{sessix,1}.cluid{params.probe{sessix}(1)}, sessparams{sessix,2}.cluid{params.probe{sessix}(2)} };
        params.cluid_all{sessix} = cell2mat(params.cluid{sessix}');
        params.probeid{sessix} = {sessparams{sessix,1}.probeid{params.probe{sessix}(1)}, sessparams{sessix,2}.probeid{params.probe{sessix}(2)} };
        params.probeid_all{sessix} = cell2mat(params.probeid{sessix}');

        objs(sessix) = sessobj{sessix,1};

        if behav_only
            continue;
        end

        objs(sessix).psth = cat(2, objs(sessix).psth{1}, sessobj{sessix,2}.psth{2});
        objs(sessix).trialdat = cat(2, objs(sessix).trialdat{1}, sessobj{sessix,2}.trialdat{2});
        objs(sessix).presampleFR = cat(1, objs(sessix).presampleFR{1}, sessobj{sessix,2}.presampleFR{2});
        objs(sessix).presampleSigma = cat(1, objs(sessix).presampleSigma{1}, sessobj{sessix,2}.presampleSigma{2});

        % assign trialtm_aligned for 2nd probe
        for i = 1:numel(objs(sessix).clu{2})
            objs(sessix).clu{2}(i).trialtm_aligned = sessobj{sessix,2}.clu{2}(i).trialtm_aligned;
        end
    end
end

disp(' ')
disp('DATA LOADED AND PROCESSED')
disp(' ')


clear obj
obj = objs;
clear objs


%% convert params to a struct array (just for convenience)

temp = params;
clear params
for sessix = 1:numel(meta)
    temp2 = rmfield(temp,{'probe','trialid','cluid','cluid_all','probeid','probeid_all'});
    temp2.probe = temp.probe{sessix};
    temp2.trialid = temp.trialid{sessix};
    temp2.cluid = temp.cluid{sessix};
    temp2.cluid_all = temp.cluid_all{sessix};
    temp2.probeid = temp.probeid{sessix};
    temp2.probeid_all = temp.probeid_all{sessix};
    params(sessix) = temp2;
end
function [params,obj] = processData(obj,params,prbnum, varargin)

% varargin only accepts one input right now -> params.behav_only. If 1,
% don't process clusters
if nargin > 3
    behav_only = varargin{1};
else
    behav_only = 0;
end

%% STANDARD ROUTINES
% find trials to use (only need to do this once)
if prbnum==1 || ~isfield(params,'trialid')
    params.trialid = findTrials(obj, params.condition);
    disp(' ')
    disp('--Trials Found')
    disp(' ')
end

% find clusters to use
params.cluid{prbnum} = findClusters({obj.clu{prbnum}(:).quality}', params.quality);
disp(' ')
disp('--Clusters Found')
disp(' ')

if behav_only
    return
end

% align spikes in every cluster to an event
obj = alignSpikes(obj,params,prbnum);
disp(' ')
disp('--Spikes Aligned')
disp(' ')

% get trial avg psth and single trial data
if ~isfield(params,'bctype') % boundary condition for smoothing
    params.bctype = 'none';
end
obj = getSeq(obj,params,prbnum);
disp(' ')
disp('--PSTHs and Single Trial Data Done')
disp(' ')


% remove low fr clusters
[obj, params.cluid{prbnum}] = removeLowFRClusters(obj,params.cluid{prbnum},params.lowFR,prbnum);
params.probeid{prbnum} = ones(size(params.cluid{prbnum})) * prbnum;
disp(' ')
disp('--Removed Low Firing Rate Clusters')
disp(' ')

% get mean fr and std dev for each cluster/trial type during presample (baseline fr)
[obj.presampleFR{prbnum}, obj.presampleSigma{prbnum}] = baselineFR(obj,params,prbnum);
disp(' ')
disp('--Presample Statisitics Calculated')
disp(' ')


end 










function obj = loadObjs(meta)
for i = 1:numel(meta)
    dat = load(meta(i).datapth);
    if ~isfield(dat.obj,'meta')
        dat.obj.meta = 'assigning to avoid dissimilar struct error';
    end
    if ~isfield(dat.obj,'ex')
        dat.obj.ex = 'assigning to avoid dissimilar struct error';
    end
    if ~isfield(dat.obj,'me')
        dat.obj.me = 'assigning to avoid dissimilar struct error';
    end
    obj(i) = dat.obj;
    clear dat
end
end % loadObjsfunction obj = alignSpikes(obj,params,prbnum)

if strcmp(params.alignEvent,'moveOnset')
    obj.bp.ev.(params.alignEvent) = findMoveOnset(obj);
end

if strcmp(params.alignEvent,'firstLick')
    % get first lick time for left and right licks
    temp = obj.bp.ev.lickL;
    idx = ~cellfun('isempty',temp);
    outL = zeros(size(temp));
    outL(idx) = cellfun(@(v)v(1),temp(idx));
    temp = obj.bp.ev.lickR;
    idx = ~cellfun('isempty',temp);
    outR = zeros(size(temp));
    outR(idx) = cellfun(@(v)v(1),temp(idx));
    firstLick = zeros(size(temp));
    % firstLick = min(outL,outR), except when outL||outR == 0
    outL(outL==0) = nan;
    outR(outR==0) = nan;
    firstLick = nanmin(outL,outR);
    firstLick(isnan(firstLick)) = 0;
    obj.bp.ev.(params.alignEvent) = firstLick;
end
if strcmp(params.alignEvent,'lastLick')
    % get last lick time for left and right licks
    temp = obj.bp.ev.lickL;
    idx = ~cellfun('isempty',temp);
    outL = zeros(size(temp));
    outL(idx) = cellfun(@(v)v(end),temp(idx));
    temp = obj.bp.ev.lickR;
    idx = ~cellfun('isempty',temp);
    outR = zeros(size(temp));
    outR(idx) = cellfun(@(v)v(end),temp(idx));
    lastLick = zeros(size(temp));
    % lastLick = max(outL,outR), except when outL||outR == 0
    outL(outL==0) = nan;
    outR(outR==0) = nan;
    lastLick = nanmax(outL,outR);
    lastLick(isnan(lastLick)) = 0;
    obj.bp.ev.(params.alignEvent) = lastLick;
end

if strcmp(params.alignEvent,'jawOnset')
    % half rise time to first peak of jaw onset after go cue
    view = 1; % side cam
    [~,jawMask] = patternMatchCellArray(obj.traj{view}(1).featNames,{'jaw'},'all');
    feat = find(jawMask); % jaw

    % filter params
    opts.f_cut = 60; % cutoff freq for butter filt
    opts.f_n   = 2;  % filter order

    % peak finding params
    opts.minpkdist = 0.06; % number of ms around peaks to reject peaks
    opts.minpkprom = 10;   % a threshold for the peak size
    obj.bp.ev.(params.alignEvent) = alignJawOnset(view,feat,obj,opts);
end

% align spikes to params.alignEvent
for clu = 1:numel(obj.clu{prbnum})
    event = obj.bp.ev.(params.alignEvent)(obj.clu{prbnum}(clu).trial);

    obj.clu{prbnum}(clu).trialtm_aligned = obj.clu{prbnum}(clu).trialtm - event;
end

end % alignSpikes
function [obj,cluid] = removeLowFRClusters(obj,cluid,lowFR,prbnum)
% % Remove low-firing rate units, e.g., all those firing less than lowFR
%   spikes per second on average across all trials.
%   
%   The fitted observation noise (diagonal element of R) for a
%   low-firing rate unit will be small, so the neural trajectory may
%   show a deflection each time the neuron spikes.

meanFRs = mean(mean(obj.psth{prbnum},3,'omitnan'),'omitnan');
use = meanFRs > lowFR;

% remove low fr clusters
cluid = cluid(use);
obj.psth{prbnum} = obj.psth{prbnum}(:,use,:);
obj.trialdat{prbnum} = obj.trialdat{prbnum}(:,use,:);

end % removeLowFRClustersfunction temp = loadKinData(meta,runix)

pth = meta.datapth;
anm = meta.anm;
date = meta.date;

pth = fullfile(pth,'kinematics');

anm_date = [anm '_' date];

if isempty(runix)
    runix = getMostRecentRun(fullfile(pth,'input'),anm_date);
end

infn = ['kin_' anm_date '_' runix '.mat'];

temp = load(fullfile(pth,infn));




endfunction me = loadMotionEnergy(obj,meta,params,datapth,varargin)

if nargin > 4
    returnAfterLoad = varargin{1};
else
    returnAfterLoad = 0;
end

% %------------------------------------------------------------
% % --first check to see if obj has an 'me' and has thresh--
% % -----------------------------------------------------------
% if isfield(obj,'me')
%     if isstruct(obj.me) && ~iscell(obj.me.data)
%         obj.me.move = obj.me.data > (obj.me.moveThresh);
%         me = obj.me;
%         return
%     end
% else
% -----------------------------------------------------------
% -- if not, loadMotionEnergy, and save it it to obj.me--
% -----------------------------------------------------------

% find and load motion energy .mat file
mepth = fullfile(datapth,'DataObjects',meta.anm);
contents = dir(mepth);
contents = contents(~[contents.isdir]);

fns = {contents.name}';

fn = patternMatchCellArray({contents.name}',{'motionEnergy',meta.date},'all');

if numel(fn) == 1
    fn = fn{1};
elseif numel(fn) == 2
    ix = ~contains(fn,'._'); % on windows, sometimes a file that starts with '._motionEnergy*' is found
    fn = fn{ix};
else
    disp('UNABLE TO LOCATE A MOTION ENERGY FILE IN: ')
    disp(mepth)
    disp('      Continuing without motion energy as a feature')
    me.use = 0;
    me.data = nan;
    me.moveThresh = nan;
    return
end

temp = load(fullfile(mepth,fn));
me = temp.me;

if isstruct(me.data)
    me.data = me.data.data;
end

if returnAfterLoad
    return
end

vidshift = findVideoOffset(obj);
% vidshift = 1;

% -----------------------------------------------------------
% trim trial length (me.data contains motion energy for each time point in
% trial at 400 Hz). Want to align to params.alignEvent and want to put it
% in same dt as neural data
% -----------------------------------------------------------
taxis = obj.time + params.advance_movement;
alignTimes = obj.bp.ev.(params.alignEvent);
me.newdata = zeros(numel(obj.time),numel(me.data));
for trix = 1:numel(me.data)
    try
        me.newdata(:,trix) = interp1(obj.traj{1}(trix).frameTimes-vidshift-alignTimes(trix),me.data{trix},taxis); % interp1(old_time,me,new_time);
    catch % if frameTimes doesn't exist or is full of NaNs - shouldn't be dummy data as we aren't using those sessions
        frameTimes = (1:size(obj.traj{1}(trix).ts,1)) ./ 400;
        me.newdata(:,trix) = interp1(frameTimes-0.5-alignTimes(trix),me.data{trix},taxis);
    end
end

% replace me.data with me.newdata
me.data = me.newdata;
me = rmfield(me,'newdata');
% fill nans with nearest value (there are some nans at the start of each
% trial)
me.data = fillmissing(me.data,'nearest');

% -------------------------------------------------------------------
% -- assign move time points as logical array same size as me.data --
% -------------------------------------------------------------------
me.move = me.data > (me.moveThresh);

% % baseline subtract 
% ps = [mode(obj.bp.ev.bitStart) mode(obj.bp.ev.sample-obj.bp.ev.bitStart)] - mode(obj.bp.ev.(params.alignEvent));
% for i = 1:numel(ps)
%     [~,psix(i)] = min(abs(obj.time - ps(i)));
% end
% psme = mean(me.data(psix(1):psix(2),:),1);
% me.data = me.data - psme;

end % loadMotionEnergy














