% operates on first dimension only - make sure first dim is time
% gaussian kernel with window size N
% varargin:
%   'reflect' - reflect N elements from beginning of time series across
%               0 index
%   'zeropad' - pad N zeros across 0 index
%   'none'    - don't handle boundary conditions

% returns:
% - out: filtered data, same size as x
% - kernsd: std dev of gaussian kernel

% % example usage:
% x = 5*sin(1:0.01:100)';
% y = x + randn(size(x));
% N = 51;
% out = mySmooth(y,N,'reflect');
% 
% figure;
% subplot(3,1,1); plot(x);
% xlim([-100 200])
% subplot(3,1,2); plot(y)
% xlim([-100 200])
% subplot(3,1,3); plot(out); %hold on; plot(out,'.','MarkerSize',6)
% xlim([-100 200])


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

if N == 0 || N == 1 % no smoothing
    out = x;
    kernsd = 0;
    return
end

if isrow(x) % if 1-d time series, ensure column vector
    x = x';
end

if nargin > 2
    % handle a boundary condition
    bctype = varargin{1};
    if strcmpi(bctype,'reflect')
        x_filt = cat(1,x(1:N,:),x);
        trim = N + 1;
    elseif strcmpi(bctype,'zeropad')
        x_filt = cat(1,zeros(N,size(x,2)),x);
        trim = N + 1;
    elseif strcmpi(bctype,'none')
        x_filt = x;
        trim = 1;
    else
        warning('invalid boundary condition type - regular smoothing');
        x_filt = x;
        trim = 1;
    end
else
    % no bc handling
    x_filt = x;
    trim = 1;
end



Ncol = size(x_filt, 2);
Nel = size(x_filt, 1);

kern = gausswin(N);
kernsd = std(1:N);


kern(1:floor(numel(kern)/2)) = 0; %causal
kern = kern./sum(kern);

out = zeros(Nel, Ncol);
for j = 1:Ncol
    out(:, j) = conv(x_filt(:, j), kern, 'same');
end
out = out(trim:end,:);

endfunction fil_space = NDgaussian(D,fsize,sigma)
	%filter size = 2 * fsize + 1
	filter_range = single(-fsize:fsize);

	% Create 1D gaussian distribution
	fil_space = 1/sigma/sqrt(2*pi)*exp(-0.5*filter_range.^2/sigma^2);
	fil_space = single(mat2gray(fil_space'));
	fil_temp = fil_space;

    % Extend it to N-D
	for i = 2:D
		fil_temp2 = fil_space;
		fil_space = fil_space*fil_temp(1);
		for j = 2:length(fil_temp)
			fil_space = cat(i,fil_space,fil_temp2*fil_temp(j));
		end
		fil_space = single(mat2gray(fil_space));
	end
end
function [xpos, ypos] = findPosition(taxis, obj, nTrials, view, feat, alignEv)

traj = obj.traj{view};

featix = findDLCFeatIndex(obj.traj,view,{feat});

xpos = nan(numel(taxis),nTrials);
ypos = nan(numel(taxis),nTrials);

vidshift = findVideoOffset(obj);
% vidshift = 1;

for i = 1:nTrials % for each trial

    trix = i;

    % check if video data for trial is good, skip if not
    if isfield(traj(trix),'NdroppedFrames')
        if isnan(traj(trix).NdroppedFrames )
            continue;
        end
    end

    % check if frameTimes exists, if not, create it
    if ~isfield(traj(trix),'frameTimes')
        traj(trix).frameTimes = (1:size(traj(trix).ts,1)) ./ 400;
    end

    % get feat trajs for valid trials
    if ~isnan(traj(trix).frameTimes)
        ts = traj(trix).ts(:,1:2,featix);
        % if tongue, don't smooth
        if ~contains(feat,'tongue')
            ts = mySmooth(ts, 1, 'reflect');
        end
        % linear interpolation of frameTimes to taxis
        tsinterp = interp1(traj(trix).frameTimes-vidshift-obj.bp.ev.(alignEv)(trix), ts, taxis);
    end

    xpos(:,i) = tsinterp(:,1);
    ypos(:,i) = tsinterp(:,2);



    % fill missing values for all features except tongue
    if ~contains(feat,'tongue')
        xpos(:,i) = fillmissing(xpos(:,i),'nearest');
        ypos(:,i) = fillmissing(ypos(:,i),'nearest');
    end

end


end  % findPosition
function kin = getKinematics(obj,me,params)

% ----------------------------------------------
% -- Check if obj already has kin --
% ----------------------------------------------
if isfield(obj,'kin')
    if isfield(params,'reload_kin')
        if params.reload_kin
            % get kinematics
        else
            return % kin = obj.kin
        end
    end
    return % kin = obj.kin
else
    % get kinematics
end


% ----------------------------------------------
% -- Kinematics --
% (xdisp,ydisp,xvel,yvel) for each dlc feature
% ----------------------------------------------
[kin.dat,kin.featLeg,kin.nans] = getKinematicsFromVideo(obj,params);

% ----------------------------------------------
% -- Tongue angle and length --
% ----------------------------------------------
if ismember('tongue',params.traj_features{1})
    [ang,len] = getLickAngleAndLength(kin.featLeg,kin.dat,kin.nans);
    kin.featLeg{end+1} = 'tongue_angle';
    kin.featLeg{end+1} = 'tongue_length';

    kin.dat(:,:,end+1) = ang;
    kin.dat(:,:,end+1) = len;
end

% ----------------------------------------------
% -- Motion energy --
% ----------------------------------------------
kin.featLeg{end+1} = 'motion_energy';

kin.dat(:,:,end+1) = me.data;

% ----------------------------------------------
% -- Standardize kinematics --
% ----------------------------------------------
for featix = 1:size(kin.dat,3)
    temp = kin.dat(:,:,featix);
    temp2 = temp(:);
    kin.dat_std(:,:,featix) = (temp - mean(temp2,'omitnan')) ./ std(temp2,'omitnan'); 
end

% ----------------------------------------------
% -- DIMENSIONALITY REDUCTION --
% ----------------------------------------------
% many of the video features will be highly correlated, so we will perform PCA/FA
% on the matrix of features to reduce the dimensionality to a set of factors that
% best explain the movement captured by the video recordings
kin.dat_reduced = reduceDimensionVideoFeatures(kin.dat,params.feat_varToExplain);

end



%% context decoding from dlc features

clearvars -except datapth kin me meta obj params acc acc_shuf

% params
rez.nFolds = 4; % number of iterations (bootstrap)

rez.binSize = 75; % ms
rez.dt = floor(rez.binSize / (params(1).dt*1000)); % samples
rez.tm = obj(1).time(1:rez.dt:numel(obj(1).time));
rez.numT = numel(rez.tm);

rez.train = 1; % fraction of trials to use for training (1-train for testing)

rez.nShuffles = 4;

% match number of right and left hits, and right and left misses
cond2use = 1:4;
afccond = [1 2];
awcond = [3 4];

% featGroups = {{'tongue'},...
%     {'jaw','trident'},...
%     {'nose','nostril'},...
%     {'paw'},...
%     {'motion_energy'}};

featGroups = {'all'};

for ifeat = 1:numel(featGroups)
    disp(['Feature Group ' num2str(ifeat) '/' num2str(numel(featGroups))])
    %     rez.feats2use = kin(1).featLeg;
    % rez.feats2use = {'jaw_ydisp_view1'};
    % rez.feats2use = {'motion_energy'};
    % rez.feats2use = {'view2'};


    rez.feats2use = featGroups{ifeat};

    if strcmpi(rez.feats2use,'all')
        rez.featix = 1:numel(kin(1).featLeg);
    else

        if size(rez.feats2use,1) == 1
            rez.feats2use = rez.feats2use';
        end

        [~,mask] = patternMatchCellArray(kin(1).featLeg,rez.feats2use,'any');
        if sum(mask) == 0
            [~,mask] = patternMatchCellArray(kin(1).featLeg,rez.feats2use,'all');
        end
        if sum(mask) == 0
            use = zeros(size(kin(1).featLeg));
            for i = 1:numel(kin(1).featLeg)
                for j = 1:numel(rez.feats2use)
                    if contains(kin(1).featLeg{i},rez.feats2use{j})
                        use(i) = 1;
                    end
                end
            end
            mask = logical(use);
        end
        if sum(mask) == 0
            error('didnt find features to use')
        end
        rez.featix = find(mask);

    end



    for sessix = 1:numel(obj)
        disp(['Decoding session ' num2str(sessix) ' / ' num2str(numel(obj))])

        % trials

        trials_cond = params(sessix).trialid(cond2use);

        minAFCTrials = cellfun(@(x) numel(x),trials_cond(afccond), 'UniformOutput',false);
        nafc = min(cell2mat(minAFCTrials));

        minAWTrials = cellfun(@(x) numel(x),trials_cond(awcond), 'UniformOutput',false);
        naw = min(cell2mat(minAWTrials));

        nTrials = min(nafc,naw);

        trials_afc = cellfun(@(x) randsample(x,nTrials), trials_cond(afccond), 'UniformOutput', false);
        trialsAFC = cell2mat(trials_afc);
        trialsAFC = trialsAFC(:);

        trials_aw = cellfun(@(x) randsample(x,nTrials), trials_cond(awcond), 'UniformOutput', false);
        trialsAW = cell2mat(trials_aw);
        trialsAW = trialsAW(:);

        trials.all = [trialsAFC ; trialsAW];

        % labels (1 for right choice, 0 for left choice)
        Y = [ones(nTrials,1) ; ones(nTrials,1) ; -ones(nTrials,1) ; -ones(nTrials,1)]; % right hits, left hits, left miss, right miss
        % Y = [ones(nhits,1) ; -ones(nhits,1) ; ones(nmiss,1) ; -ones(nmiss,1)]; % right hits, left hits, left miss, right miss

        % input
        X = obj(sessix).trialdat(:,:,trials.all);
        X = permute(X,[1 3 2]); % (time,trials, clu)
        Xmax = max(X(:));
        Xmin = min(X(:));
        Range = Xmax - Xmin;
        Xnrm = ((X - Xmin)/Range - 0.5) * 2;
        X = Xnrm; clear Xnrm;

        % train/test split
        [trials.train,trials.trainidx] = datasample(trials.all,round(numel(trials.all)*rez.train),'Replace',false);
        trials.testidx = find(~ismember(trials.all,trials.train));
        trials.test = trials.all(trials.testidx);

        in.train.y = Y(trials.trainidx);
        in.test.y  = Y(trials.testidx);
        in.train.X = X(:,trials.trainidx,:);
        in.test.X  = X(:,trials.testidx,:);

        % decoding

        acc(:,sessix,ifeat) = DLC_ChoiceDecoder(in,rez,trials);


        % shuffle labels for a 'null' distribution


        Y = randsample(Y,numel(Y));

        % train/test split

        in.train.y = Y(trials.trainidx);
        in.test.y  = Y(trials.testidx);

        for ishuf = 1:rez.nShuffles
            acc_shuf(:,sessix,ishuf,ifeat) = DLC_ChoiceDecoder(in,rez,trials);
        end


    end

end

acc_shuf_ = reshape(acc_shuf,size(acc_shuf,1),size(acc_shuf,2)*size(acc_shuf,3));

