probe={'JEB6':2,'JEB7':1,'EKH1':2,'EKH3':2,'JGR2':1,'JGR3':1,'JEB19':1};tot=0
for p in sorted(Path('data/Ephys_Behavior').glob('data_structure_*.mat')):
 a=p.stem.split('_')[2]
 if a not in probe:continue
 with h5py.File(p) as f:
  bp=f['obj/bp'];go=np.asarray(bp['ev/goCue']).ravel();n=len(go);hit=np.asarray(bp['hit']).ravel().astype(bool);miss=np.asarray(bp['miss']).ravel().astype(bool);early=np.asarray(bp['early']).ravel().astype(bool);aw=np.asarray(bp['autowater']).ravel().astype(bool);cond=[np.ones(n,bool),hit&~aw,hit&aw,miss&~aw,miss&aw,hit&~aw&~early,hit&aw&~early]
  g=f[f['obj/clu'][probe[a]-1,0]];cnt=0
  for i in range(g['quality'].shape[0]):
   q=''.join(map(chr,np.asarray(f[g['quality'][i,0]]).ravel())).strip().replace('\x00','')
   if q in {'garbage','gabrga','noisy','real?'}:continue
   tr=np.asarray(f[g['trial'][i,0]]).ravel().astype(int)-1;tt=np.asarray(f[g['trialtm'][i,0]]).ravel();ok=(tr>=0)&(tr<n);tr=tr[ok];al=tt[ok]-go[tr];rr=[]
   for c in cond: rr.append(np.count_nonzero((al>=-3)&(al<2.5)&c[tr])/(c.sum()*5.5) if c.sum() else 0)
   cnt+=np.mean(rr)>1
  print(p.stem.replace('data_structure_',''),cnt);tot+=cnt
print(tot)
